package com.wtm.importer;
import java.time.LocalDate; import java.time.format.DateTimeFormatter; import java.time.temporal.IsoFields; import java.util.*;
public final class DailyLhyKpiProfile implements KpiCsvImportProfile{
 public boolean supports(CsvTable t){return t.headers().contains("logdate")&&t.headers().contains("lhy");}
 public KpiImportResult parse(CsvTable t)throws Exception{LocalDate first=null,last=null,linesDate=null;Double lines=null;List<String>w=new ArrayList<>();List<KpiImportedMetric>history=new ArrayList<>();TreeMap<LocalDate,Double>daily=new TreeMap<>();for(Map<String,String>r:t.rows()){LocalDate d=date(r.get("logdate"));if(d==null){w.add("Skipped a row with an invalid LOGDATE.");continue;}if(first==null||d.isBefore(first))first=d;if(last==null||d.isAfter(last))last=d;Double lv=num(r.get("lhy"));if(lv!=null){daily.put(d,lv);history.add(new KpiImportedMetric("lhy","LHY Performance",lv,"",d,"CSV_LHY"));}Double ov=num(r.get("orderlines"));if(ov!=null){history.add(new KpiImportedMetric("lines","Lines Shipped",ov," lines",d,"CSV_LHY"));if(linesDate==null||!d.isBefore(linesDate)){lines=ov;linesDate=d;}}}if(daily.isEmpty())throw new IllegalArgumentException("The LHY report did not contain any completed numeric LHY values.");LocalDate a=daily.lastKey();List<KpiImportedMetric>m=new ArrayList<>();m.add(new KpiImportedMetric("lhy_previous_day","LHY • Previous Day",daily.get(a),"",a,"CSV_LHY"));avg(m,daily,a,0,"lhy_month_avg","LHY • Monthly Average");avg(m,daily,a,1,"lhy_quarter_avg","LHY • Quarterly Average");avg(m,daily,a,2,"lhy_year_avg","LHY • Annual Average");m.add(new KpiImportedMetric("lhy","LHY Performance",daily.get(a),"",a,"CSV_LHY"));if(lines!=null)m.add(new KpiImportedMetric("lines","Lines Shipped",lines," lines",linesDate,"CSV_LHY"));return new KpiImportResult("Daily LHY and LPH",t.rows().size(),first,last,m,history,w);}
 private static void avg(List<KpiImportedMetric>o,NavigableMap<LocalDate,Double>v,LocalDate a,int p,String id,String label){List<Double>x=new ArrayList<>();for(var e:v.entrySet()){LocalDate d=e.getKey();boolean ok=p==0?d.getYear()==a.getYear()&&d.getMonth()==a.getMonth():p==1?d.getYear()==a.getYear()&&d.get(IsoFields.QUARTER_OF_YEAR)==a.get(IsoFields.QUARTER_OF_YEAR):d.getYear()==a.getYear();if(ok)x.add(e.getValue());}if(x.size()<2)return;double z=x.stream().mapToDouble(Double::doubleValue).average().orElse(0);o.add(new KpiImportedMetric(id,label,z,"",a,"CSV_LHY"));}
 private static LocalDate date(String r){if(r==null||r.isBlank())return null;for(DateTimeFormatter f:List.of(DateTimeFormatter.ISO_LOCAL_DATE,DateTimeFormatter.ofPattern("M/d/uuuu"),DateTimeFormatter.ofPattern("M-d-uuuu"))){try{return LocalDate.parse(r.trim(),f);}catch(Exception ignored){}}return null;} private static Double num(String r){if(r==null)return null;String v=r.trim().replace(",","");if(v.isBlank()||v.equalsIgnoreCase("nan")||v.equalsIgnoreCase("null"))return null;try{double x=Double.parseDouble(v);return Double.isFinite(x)?x:null;}catch(Exception e){return null;}}
}